252	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
253	        return Collections.unmodifiableList(sortedPets);
254	    }
255	
256	    public void setPets(List<Pet> pets) {
257	        this.pets = new HashSet<>(pets);
258	    }
