265	    /**
266	     * Return the Pet with the given name, or null if none found for this Owner.
267	     *
268	     * @param name to test
269	     * @return true if pet name is already in use
270	     */
271	    public Pet getPet(String name) {
272	        return getPet(name, false);
273	    }
274	
275	    /**
276	     * Return the Pet with the given name, or null if none found for this Owner.
277	     *
278	     * @param name to test
279	     * @return true if pet name is already in use
280	     */
281	    public Pet getPet(String name, boolean ignoreNew) {
282	        name = name.toLowerCase();
283	        for (Pet pet : getPetsInternal()) {
284	            if (!ignoreNew || !pet.isNew()) {
285	                String compName = pet.getName();
286	                compName = compName.toLowerCase();
287	                if (compName.equals(name)) {
288	                    return pet;
289	                }
290	            }
291	        }
292	        return null;
293	    }
294	
295	    public Pet getPet(Integer petId) {
296	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
297	    }
298	
299	    @Override
300	    public String toString() {
301	        return new ToStringCreator(this)
302	
303	            .append("id", this.getId())
304	            .append("new", this.isNew())
305	            .append("lastName", this.getLastName())
306	            .append("firstName", this.getFirstName())
307	            .append("address", this.address)
308	            .append("city", this.city)
309	            .append("telephone", this.telephone)
310	            .append("email", this.email)
311	            .toString();
312	    }
313	}
